import{z as l,x as s,o as e,c as n,q as t,j as A,D as E,d as i,s as B,S as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"缺陷检测：光学与电子束","description":"","frontmatter":{"title":"缺陷检测：光学与电子束","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/defect-inspection-optical-ebeam.md","filePath":"litho/defect-inspection-optical-ebeam.md","lastUpdated":1791413859000}'),p={name:"litho/defect-inspection-optical-ebeam.md"};function d(c,a,D,h,C,_){const o=s("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="缺陷检测-光学与电子束" tabindex="-1">缺陷检测：光学与电子束 <a class="header-anchor" href="#缺陷检测-光学与电子束" aria-label="Permalink to &quot;缺陷检测：光学与电子束&quot;">​</a></h1><div class="epigraph"><p>光学检测买面积与速度，电子束买分辨率与材料衬度；随机缺孔和细桥往往落在光学的盲区，必须由电子束抽样补上。</p><footer>—— 对照 KLA 一类对宽带等离子体 / 激光检测与电子束检测的公开分工；[图形化检测设备](/litho/patterning-inspection-tools) 已列角色</footer></div><p><a href="/litho/stochastic-yield">上一课</a>要求看见 ppb 级事件。缺口是仪器：<a href="/litho/patterning-inspection-tools">图形化检测设备</a> 已分检测与量测；本课钉光学对电子束在<strong>图形化缺陷</strong>上的能力边界，不重写工具市场。复检与分类，留给<a href="/litho/defect-review-classification">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>亮场/暗场光学（激光或宽带等离子体）扫整片，找颗粒、大桥、残胶、剥离。分辨率与光学噪声限制了最小致命缺陷，尤其是 EUV 后的细桥与缺孔。电子束检测（EBI）分辨率够，吞吐低，只能抽场、抽阵列。合同：光学做全片随机颗粒与大系统缺陷；电子束做热区、孔阵列、SRAM 的随机计数。</p><p>缺口是<strong>漏检对良率 Pareto 的偏置</strong>，不是再介绍 KLA。只看光学 Pareto 会低估 stoch、高估大颗粒。PWQ 必须声明用哪类检测。</p><h3 id="检测不是量测" tabindex="-1">检测不是量测 <a class="header-anchor" href="#检测不是量测" aria-label="Permalink to &quot;检测不是量测&quot;">​</a></h3><p>CD-SEM 不扫整片找缺陷；缺陷检测不报准确 CD。混用机时会把 APC 样本和缺陷样本抢崩。设备课已强调；本课从良率数据链再钉一次。</p><p><span class="marginnote">同一次光学扫描的灵敏度配方（阈值、像素）决定 Pareto。换配方等于换计量机，要重新匹配历史。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光学：全片、多模式（亮/暗、多波长）。电子束：热点 clips、via 阵列、PWQ 矩阵。抽样：与随机 \\(N\\) 匹配，否则 \\(p\\) 的置信区间跨数量级。与 ADC（自动缺陷分类）预筛，细类留给复检课。与边缘：光学对边缘剥落敏感，注意与部分场失焦区分。</p><p>电子束抽样点要固定一套「随机哨兵」阵列，才能做周与周的 \\(p\\) 比较。换 clips 等于换计量。KLA 一类公开材料把光学与电子束当互补覆盖；本课把互补写成两份不可互相替代的 Pareto 输入。</p><p>一份周度检测计划怎么把两类仪器排成一条流水线？光学先全片扫出地形，电子束再对哨兵阵列做人口普查，两份账最后合进良率 Pareto，缺了哪份都是偏的。</p>',13)),(e(),A(r,null,{default:E(()=>[B(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E5%85%89%E5%AD%A6%EF%BC%9A%E5%85%A8%E7%89%87%E5%A4%9A%E6%A8%A1%E5%BC%8F%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20HIT%5B%22%E5%AE%9A%E4%BD%8D%E7%83%AD%E5%8C%BA%E4%B8%8E%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%A4%A7%E7%BC%BA%E9%99%B7%22%5D%0A%20%20HIT%20--%3E%20E%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%EF%BC%9A%E5%9B%BA%E5%AE%9A%E5%93%A8%E5%85%B5%E9%98%B5%E5%88%97%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20E%20--%3E%20N%5B%22%E6%95%B0%E9%9A%8F%E6%9C%BA%E7%BC%BA%E5%AD%94%20%2F%20%E7%BB%86%E6%A1%A5%EF%BC%8C%E5%BE%97%20p%20%E7%9A%84%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%22%5D%0A%20%20N%20--%3E%20WK%7B%22%E4%B8%8E%E4%B8%8A%E5%91%A8%E5%8F%AF%E6%AF%94%E5%90%97%EF%BC%9F%22%7D%0A%20%20WK%20--%3E%7C%22%E5%90%8C%E4%B8%80%E5%A5%97%20clips%20%E4%B8%8E%E9%85%8D%E6%96%B9%22%7C%20TREND%5B%22%E5%91%A8%E9%97%B4%E8%B6%8B%E5%8A%BF%E6%9C%89%E6%95%88%22%5D%0A%20%20WK%20--%3E%7C%22%E6%8D%A2%E4%BA%86%20clips%20%E6%88%96%E9%98%88%E5%80%BC%22%7C%20RESET%5B%22%E5%8E%86%E5%8F%B2%E6%96%AD%E7%BA%BF%EF%BC%8C%E9%87%8D%E6%96%B0%E5%9F%BA%E7%BA%BF%E5%8C%96%22%5D%0A%20%20TREND%20--%3E%20P%5B%22%E5%90%88%E5%B9%B6%E8%BF%9B%E8%89%AF%E7%8E%87%20Pareto%EF%BC%8C%E4%BF%AE%E6%AD%A3%E6%BC%8F%E6%A3%80%E5%81%8F%E7%BD%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">术语翻译：Pareto（帕累托图）就是「按罪魁祸首排序的缺陷排行榜」——最长的柱子是当前最值得修的失效类别。要注意光学扫出来的榜和电子束抽出来的榜可能第一名完全不同：一个被大颗粒霸榜，一个被缺孔霸榜，合起来才是真相。</span></p><p><span class="marginnote">数字实例：设电子束只能抽全片 \\(1\\%\\) 的场，若哨兵阵列里数出 \\(5\\) 个缺孔，外推到整片约是数百个量级，但抽样太少时 \\(p\\) 的置信区间可以横跨数量级——所以哨兵必须固定、逐周累计，而不是每周换地方零星看几眼。</span></p><p><span class="marginnote">常见误区：初学者容易把「没扫到」读成「没有缺陷」。光学分辨率以下的细桥与缺孔不是不存在，只是信号淹没在图形噪声里。只信光学 Pareto，工艺改进就会一直去抓大颗粒，而真正限良率的随机事件（stochastic 缺陷）始终躲在榜外。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学散射截面随缺陷体积与材料对比走，亚分辨率缺陷信号淹没在图形噪声里。电子束二次电子衬度看形貌与材料，慢。漏检率进入 \\(D\\) 与 \\(p\\) 的估计偏置：光学漏小缺陷 → 关键面积模型用错尺寸分布。</p>',5)),(e(),A(r,null,{default:E(()=>[B(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E5%85%89%E5%AD%A6%E5%85%A8%E7%89%87%22%5D%20--%3E%20BIG%5B%22%E9%A2%97%E7%B2%92%20%2F%20%E5%A4%A7%E6%A1%A5%20%2F%20%E5%89%A5%E7%A6%BB%22%5D%0A%20%20EBI%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%E6%8A%BD%E6%A0%B7%22%5D%20--%3E%20STO%5B%22%E7%BC%BA%E5%AD%94%20%2F%20%E7%BB%86%E6%A1%A5%20%2F%20%E7%83%AD%E5%8C%BA%22%5D%0A%20%20BIG%20--%3E%20PAR%5B%22Pareto%22%5D%0A%20%20STO%20--%3E%20PAR%0A%20%20MISS%5B%22%E6%BC%8F%E6%A3%80%22%5D%20--%3E%20BIAS%5B%22D%20%E4%B8%8E%20p%20%E5%81%8F%E7%BD%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>光学 Pareto 与电子束 Pareto 不可互相替代。漏检会偏置 D 与 p，PWQ 必须声明用了哪类探测器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不报未公开的每小时片数。不把商标当物理。复检 SEM 的分类下一课才做，本课只到「找到」。</p><p>后课默认：光学全片 + 电子束抽热区，Pareto 才完整。下一课把检出物变成可行动的类。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光学覆盖面积，电子束覆盖致命小缺陷与随机计数。</li><li>漏检偏置 \\(D\\) 与 \\(p\\)；PWQ 要声明探测器。</li><li>检测与 CD 量测机时分家。</li><li>出处：晶圆缺陷检测公开分工；KLA / 电子束检测公开方法。</li></ul>',6))])}const F=l(p,[["render",d]]);export{P as __pageData,F as default};
